let activeRun=null;
function escapeText(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const storyQuests=[
{id:'firefly',title:'Den vilsekomna eldflugan',route:2,icon:'✦',reward:60,trust:25,item:'lantern',intro:'En liten eldfluga har tappat bort sin familj i Månskensmyren. Följ ljuset, hitta henne och hjälp henne hem.',steps:['Leta bland tuvorna','Ett svagt ljus längre fram…','Där är hon! Eldflugan följer med dig.','Följ familjens ljuspunkter','Familjen väntar vid nästa tuva','Tillsammans igen! Eldflugorna dansar av glädje.']},
{id:'jewel',title:'Astrids försvunna kronjuvel',route:1,icon:'◆',reward:80,trust:30,item:'crystal',intro:'Min kronjuvel rullade iväg i Svampskogen. Följ de glittrande spåren och ta med den hem. Jag litar på dig!',steps:['Följ glittret mellan svamparna','Ett spår bakom roten…','Du hittade kronjuvelen!','Bär den varsamt genom skogen','Slottets glänta är nära','Kronjuvelen är hemma hos Astrid!']}
];
const decorations=[{id:'flowers',name:'Ängsblommor',icon:'🌼',cost:0},{id:'cushion',name:'Mosskudde',icon:'🌿',cost:70},{id:'house',name:'Litet svamphus',icon:'🍄',cost:120},{id:'pond',name:'Minidamm',icon:'💧',cost:90},{id:'lantern',name:'Eldflugelykta',icon:'🏮',quest:'firefly'},{id:'crystal',name:'Kristallblomma',icon:'💎',quest:'jewel'},{id:'trophy',name:'Kunglig pokal',icon:'🏆',cup:true}];
function storyProgress(id){return state.adventures[id]||{steps:0,done:false}}
function grantDecoration(id){if(!state.decorOwned.includes(id))state.decorOwned.push(id)}
function completeAdventure(id){const q=storyQuests.find(q=>q.id===id),p=storyProgress(id);if(!q||p.done||p.steps<6)return false;p.done=true;state.adventures[id]=p;state.coins+=q.reward;state.trust+=q.trust;grantDecoration(q.item);save();return true}
function advanceAdventure(id){const p=storyProgress(id);if(p.done)return;p.steps=Math.min(6,p.steps+1);state.adventures[id]=p;save()}
function renderAdventures(){$('#content').innerHTML=`<div class="sectionHead"><h2>Äventyr med Astrid</h2><span class="pill">Upptäck · hjälp · hitta hem</span></div><div class="storyWelcome"><img src="assets/astrid-portrait.png" alt="Astrid"><p>”Mitt rike behöver både modiga hopp och vänliga hjärtan. Ta den tid du behöver – jag tror på dig!”</p></div><div class="royalQuests">${storyQuests.map(q=>{const p=storyProgress(q.id);return `<article class="quest"><div class="storyIcon">${q.icon}</div><h3>${q.title}</h3><p>${q.intro}</p><p><strong>${p.done?'✓ Hemma igen':p.steps+' / 6 etapper'}</strong><br>${q.reward} daggdroppar · ${q.trust} förtroende<br>Gåva: ${decorations.find(d=>d.id===q.item).name}</p><button class="primary" data-story="${q.id}" ${p.done?'disabled':''}>${p.done?'Uppdrag slutfört':p.steps?'Fortsätt äventyret':'Ge dig ut →'}</button></article>`}).join('')}</div><p class="royalExplain">Ingen tidspress och inga motståndare. Sex lyckade hopp tar dig genom berättelsen. Du kan pausa och fortsätta senare.</p>`;document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{const q=storyQuests.find(q=>q.id===b.dataset.story);if(storyProgress(q.id).done)return;activeRun={kind:'adventure',id:q.id};chosen=q.route;startRace()})}
function adventureEnding(id){const q=storyQuests.find(q=>q.id===id);completeAdventure(id);sidebar();$('#content').innerHTML=`<section class="queenHero"><img src="assets/astrid-crown.png" alt="Astrid tackar dig"><div><div class="eyebrow">ETT VÄNLIGT HJÄRTA</div><h2>${q.steps[5]}</h2><p>”Tack, min vän! Du har gjort älvvärlden lite ljusare.”</p><p>+${q.reward} daggdroppar · +${q.trust} förtroende</p><p>Du fick <strong>${decorations.find(d=>d.id===q.item).name}</strong> till din glänta.</p><button class="primary" id="storyHome">Inred gläntan →</button></div></section>`;$('#storyHome').onclick=()=>{tab='home';render()}}
function careAction(kind){if(!['feed','pet','play'].includes(kind))return false;if(state.careLog[kind]===state.royalRaces)return false;state.careLog[kind]=state.royalRaces;state.bond=Math.min(100,state.bond+5);save();return true}
function renderCare(){const personality={Modig:'Nyfiken på nästa stora språng och alltid redo för äventyr.',Sömnig:'Älskar en mjuk mossbädd och tar gärna en tupplur efter racet.',Busig:'Gör små glädjeskutt och gömmer sig gärna bland blommorna.'}[state.personality];$('#content').innerHTML=`<div class="sectionHead"><h2>Din bästa grodvän</h2><span class="pill">${state.personality}</span></div><section class="editor carePanel"><div class="carePortrait">${frog()}</div><label for="frogName">Grodans namn</label><input type="text" id="frogName" maxlength="20"><p>${personality}</p><label>Vänskap · ${state.bond} / 100</label><progress value="${state.bond}" max="100" aria-label="Vänskap"></progress><div class="careActions">${[['feed','🍓','Bjud på bär'],['pet','♡','Klappa'],['play','❀','Lek tillsammans']].map(([id,icon,n])=>`<button class="outline" data-care="${id}" ${state.careLog[id]===state.royalRaces?'disabled':''}>${icon} ${n}${state.careLog[id]===state.royalRaces?' ✓':''}</button>`).join('')}</div><p id="careResponse" role="status">Din groda är glad att se dig.</p><p>Omvårdnad är gratis och frivillig. Vänskapen minskar aldrig när du är borta. Efter nästa race kan ni göra aktiviteterna igen. Personligheten påverkar humöret, inte dina chanser att vinna.</p></section>`;$('#frogName').value=state.frogName;$('#frogName').oninput=e=>{state.frogName=e.target.value.trim()||'Näckros';save();sidebar()};document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>{if(careAction(b.dataset.care)){renderCare();$('#careResponse').textContent={feed:'Mums! Din groda smackar nöjt. +5 vänskap',pet:'Din groda lutar sig mot din hand. +5 vänskap',play:state.personality==='Sömnig'?'Ett litet skutt, sedan en mysig vila. +5 vänskap':'Glada skutt bland blommorna! +5 vänskap'}[b.dataset.care]}})}
function buyDecoration(id){const d=decorations.find(d=>d.id===id);if(!d||d.cost===undefined||state.decorOwned.includes(id)||state.coins<d.cost)return false;state.coins-=d.cost;grantDecoration(id);save();return true}
function setDecoration(slot,id){if(!Number.isInteger(slot)||slot<0||slot>2||id!=='none'&&!state.decorOwned.includes(id))return false;state.decorSlots[slot]=id;save();return true}
function cupUnlocked(){return state.royalRaces>=3&&storyQuests.some(q=>storyProgress(q.id).done)}
function beginCup(){if(!cupUnlocked()||state.cup&&!state.cup.done)return false;state.cup={round:0,scores:[0,0,0,0],done:false,won:false};save();return true}
function recordCupRound(order){const cup=state.cup;if(!cup||cup.done)return;const others=[1,2,3].filter(i=>!order.includes(i));const complete=[...order,...others];complete.forEach((id,i)=>cup.scores[id]+=[10,7,4,2][i]);cup.round++;if(cup.round===3){cup.done=true;cup.won=cup.scores[0]===Math.max(...cup.scores);if(cup.won){state.cupWins++;state.coins+=150;state.trust+=30;grantDecoration('trophy')}else{state.coins+=40;state.trust+=10}}save()}
function renderCup(){const cup=state.cup,open=cupUnlocked();$('#content').innerHTML=`<section class="queenHero"><img src="assets/astrid-start.png" alt="Astrid bjuder in till mästerskap"><div><div class="eyebrow">ASTRIDS KUNGLIGA MÄSTERSKAP</div><h2>${cup?.done?(cup.won?'Du är kunglig mästare!':'Tack för dina modiga språng!'):'Tre banor. En kunglig final.'}</h2><p>”Tävla i hela mitt rike! Samla poäng på alla tre banor. Jag hejar på er alla.”</p><p>Placering 1–4 ger 10, 7, 4 eller 2 poäng. Högst totalpoäng vinner. Delad förstaplats räknas som seger.</p>${open?'':`<p>Inbjudan: ${Math.min(3,state.royalRaces)} / 3 race och ${storyQuests.some(q=>storyProgress(q.id).done)?1:0} / 1 äventyr slutfört.</p>`}${cup?.done?`<p>${cup.won?'♛ Astrid kröner dig med mästarkransen! +150 daggdroppar, +30 förtroende och en pokal till gläntan.':'”Du gav inte upp, och det gör mig stolt. Försök gärna igen!” +40 daggdroppar och +10 förtroende.'}</p>`:''}<button class="primary" id="cupNext" ${!open?'disabled':''}>${cup&&!cup.done?'Fortsätt · '+races[cup.round].name:cup?.done?'Spela mästerskapet igen':'Börja mästerskapet'}</button></div></section>${cup?`<section class="editor"><h3>Kungliga poängtavlan · ${cup.round} / 3 lopp</h3>${['Ditt team','Klöver','Mossa','Pärla'].map((n,i)=>`<p class="cupScore"><span>${n}</span><strong>${cup.scores[i]} poäng</strong></p>`).join('')}</section>`:''}<p class="royalExplain">Gratis deltagande. Mästerskapet sparas efter varje lopp. Vanliga race räknas inte som mästerskapslopp.</p>${state.cupWins>0?'<button class="outline" id="wearCrown">Bär Astrids mästarkrans</button>':''}`;$('#cupNext').onclick=()=>{if(!cupUnlocked())return;if(!state.cup||state.cup.done)beginCup();activeRun={kind:'cup'};chosen=state.cup.round;astridStart()};if($('#wearCrown'))$('#wearCrown').onclick=()=>{state.headwear='champion';save();tab='fairy';render()}}
